func newKey() unsafe.Pointer { return unsafe.Pointer(new(apikey.Key)) }

func newNKey(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]apikey.Key, n))) }

func ptrKey(p unsafe.Pointer, c int32) any {
	r := (*apikey.Key)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.Name
	case 4:
		return &r.Description
	case 5:
		return &r.KeyPrefix
	case 6:
		return &r.SecretHash
	case 7:
		return &r.SecretSalt
	case 8:
		return (*string)(unsafe.Pointer(&r.Status))
	case 9:
		return &r.ExpiresAt
	case 10:
		return &r.LastUsedAt
	case 11:
		return &r.LastUsedIP
	case 12:
		return &r.LastUsedUserAgent
	case 13:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 14:
		return (*string)(unsafe.Pointer(&r.RevokedByID))
	case 15:
		return &r.RevokedAt
	case 16:
		return &r.CreatedAt
	case 17:
		return &r.UpdatedAt
	}
	return nil
}

func valueKey(p unsafe.Pointer, c int32) any {
	r := (*apikey.Key)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.Name
	case 4:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 5:
		return r.KeyPrefix
	case 6:
		return r.SecretHash
	case 7:
		return r.SecretSalt
	case 8:
		return string(r.Status)
	case 9:
		if r.ExpiresAt == 0 {
			return nil
		}
		return r.ExpiresAt
	case 10:
		if r.LastUsedAt == 0 {
			return nil
		}
		return r.LastUsedAt
	case 11:
		if r.LastUsedIP == "" {
			return nil
		}
		return r.LastUsedIP
	case 12:
		if r.LastUsedUserAgent == "" {
			return nil
		}
		return r.LastUsedUserAgent
	case 13:
		return string(r.CreatedByID)
	case 14:
		if r.RevokedByID == "" {
			return nil
		}
		return string(r.RevokedByID)
	case 15:
		if r.RevokedAt == 0 {
			return nil
		}
		return r.RevokedAt
	case 16:
		return r.CreatedAt
	case 17:
		return r.UpdatedAt
	}
	return nil
}

func attachKey(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*apikey.Key)(p)
	switch rel {
	case 0:
		r.Permissions = append(r.Permissions, (*apikey.Permission)(child))
	}
}

